-- Railway Database Dump for Fantrax Value Hunter V2.0
-- Generated from current local database
-- Contains all essential tables with current data

BEGIN;

-- Table: players (717 rows)
CREATE TABLE IF NOT EXISTS players (
    id CHARACTER VARYING NOT NULL,
    name CHARACTER VARYING NOT NULL,
    team CHARACTER VARYING,
    position CHARACTER VARYING,
    updated_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    minutes INTEGER DEFAULT 0,
    xg90 NUMERIC DEFAULT 0.000,
    xa90 NUMERIC DEFAULT 0.000,
    xgi90 NUMERIC DEFAULT 0.000,
    last_understat_update TIMESTAMP WITHOUT TIME ZONE,
    true_value NUMERIC,
    roi NUMERIC,
    formula_version CHARACTER VARYING DEFAULT 'v2.0'::character varying,
    exponential_form_score NUMERIC,
    baseline_xgi NUMERIC,
    blended_ppg NUMERIC,
    current_season_weight NUMERIC,
    games_current_season INTEGER DEFAULT 0
);


-- Table: player_metrics (711 rows)
CREATE TABLE IF NOT EXISTS player_metrics (
    player_id CHARACTER VARYING NOT NULL,
    gameweek INTEGER NOT NULL,
    price NUMERIC,
    ppg NUMERIC,
    ppg_source CHARACTER VARYING,
    value_score NUMERIC,
    true_value NUMERIC,
    form_multiplier NUMERIC DEFAULT 1.0,
    fixture_multiplier NUMERIC DEFAULT 1.0,
    starter_multiplier NUMERIC DEFAULT 1.0,
    last_updated TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    xgi_multiplier NUMERIC DEFAULT 1.000,
    games_current_season INTEGER DEFAULT 0,
    imported_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    csv_confidence_multiplier NUMERIC DEFAULT 0.35
);


-- Table: player_games_data (2,002 rows)
CREATE TABLE IF NOT EXISTS player_games_data (
    player_id CHARACTER VARYING NOT NULL,
    gameweek INTEGER NOT NULL,
    total_points NUMERIC DEFAULT 0,
    games_played INTEGER DEFAULT 0,
    total_points_historical NUMERIC DEFAULT 0,
    games_played_historical INTEGER DEFAULT 0,
    data_source CHARACTER VARYING DEFAULT 'current'::character varying,
    last_updated TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP
);


-- Table: team_fixtures (20 rows)
CREATE TABLE IF NOT EXISTS team_fixtures (
    gameweek INTEGER NOT NULL,
    team_code CHARACTER VARYING NOT NULL,
    opponent_code CHARACTER VARYING NOT NULL,
    is_home BOOLEAN NOT NULL,
    difficulty_score NUMERIC NOT NULL,
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    imported_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP
);


-- Table: name_mappings (1,508 rows)
CREATE TABLE IF NOT EXISTS name_mappings (
    id INTEGER NOT NULL DEFAULT nextval('name_mappings_id_seq'::regclass),
    source_system CHARACTER VARYING NOT NULL,
    source_name CHARACTER VARYING NOT NULL,
    fantrax_id CHARACTER VARYING NOT NULL,
    fantrax_name CHARACTER VARYING,
    team CHARACTER VARYING,
    position CHARACTER VARYING,
    confidence_score DOUBLE PRECISION DEFAULT 0,
    match_type CHARACTER VARYING,
    verified BOOLEAN DEFAULT false,
    verification_date TIMESTAMP WITHOUT TIME ZONE,
    verified_by CHARACTER VARYING,
    last_used TIMESTAMP WITHOUT TIME ZONE,
    usage_count INTEGER DEFAULT 0,
    notes TEXT,
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP
);


-- Table: fixture_odds (10 rows)
CREATE TABLE IF NOT EXISTS fixture_odds (
    id INTEGER NOT NULL DEFAULT nextval('fixture_odds_id_seq'::regclass),
    gameweek INTEGER NOT NULL,
    match_date DATE NOT NULL,
    home_team CHARACTER VARYING NOT NULL,
    away_team CHARACTER VARYING NOT NULL,
    home_odds NUMERIC NOT NULL,
    draw_odds NUMERIC NOT NULL,
    away_odds NUMERIC NOT NULL,
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP
);


-- Table: player_form (1,357 rows)
CREATE TABLE IF NOT EXISTS player_form (
    player_id CHARACTER VARYING NOT NULL,
    gameweek INTEGER NOT NULL,
    points NUMERIC,
    timestamp TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    imported_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP
);


-- Table: player_game_scores (2,724 rows)
CREATE TABLE IF NOT EXISTS player_game_scores (
    id INTEGER NOT NULL DEFAULT nextval('player_game_scores_id_seq'::regclass),
    player_id CHARACTER VARYING NOT NULL,
    game_number INTEGER NOT NULL,
    points_scored NUMERIC,
    opponent CHARACTER VARYING,
    date_played DATE,
    import_timestamp TIMESTAMP WITHOUT TIME ZONE DEFAULT now(),
    did_play BOOLEAN
);


-- Table: raw_fixture_snapshots (40 rows)
CREATE TABLE IF NOT EXISTS raw_fixture_snapshots (
    id INTEGER NOT NULL DEFAULT nextval('raw_fixture_snapshots_id_seq'::regclass),
    gameweek INTEGER NOT NULL,
    team CHARACTER VARYING NOT NULL,
    opponent CHARACTER VARYING,
    is_home BOOLEAN,
    home_odds NUMERIC,
    draw_odds NUMERIC,
    away_odds NUMERIC,
    difficulty_score NUMERIC,
    import_timestamp TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    odds_source CHARACTER VARYING
);


-- Table: raw_form_snapshots (1,991 rows)
CREATE TABLE IF NOT EXISTS raw_form_snapshots (
    id INTEGER NOT NULL DEFAULT nextval('raw_form_snapshots_id_seq'::regclass),
    player_id CHARACTER VARYING NOT NULL,
    gameweek INTEGER NOT NULL,
    points_scored NUMERIC NOT NULL,
    minutes_played INTEGER DEFAULT 0,
    games_played INTEGER DEFAULT 0,
    import_timestamp TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP
);


-- Table: raw_player_snapshots (1,996 rows)
CREATE TABLE IF NOT EXISTS raw_player_snapshots (
    id INTEGER NOT NULL DEFAULT nextval('raw_player_snapshots_id_seq'::regclass),
    player_id CHARACTER VARYING NOT NULL,
    gameweek INTEGER NOT NULL,
    import_timestamp TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    name CHARACTER VARYING,
    team CHARACTER VARYING,
    position CHARACTER VARYING,
    price NUMERIC,
    fpts NUMERIC,
    minutes_played INTEGER DEFAULT 0,
    opponent CHARACTER VARYING,
    is_home BOOLEAN,
    fixture_difficulty NUMERIC,
    xg90 NUMERIC,
    xa90 NUMERIC,
    xgi90 NUMERIC,
    is_predicted_starter BOOLEAN,
    rotation_risk CHARACTER VARYING,
    baseline_xgi NUMERIC,
    historical_ppg NUMERIC,
    historical_games INTEGER,
    fantrax_import BOOLEAN DEFAULT false,
    understat_import BOOLEAN DEFAULT false,
    odds_import BOOLEAN DEFAULT false,
    lineup_import BOOLEAN DEFAULT false,
    games_current_season INTEGER DEFAULT 0
);


-- Table: understat_name_mappings (163 rows)
CREATE TABLE IF NOT EXISTS understat_name_mappings (
    id INTEGER NOT NULL DEFAULT nextval('understat_name_mappings_id_seq'::regclass),
    understat_name CHARACTER VARYING NOT NULL,
    fantrax_id CHARACTER VARYING NOT NULL,
    confidence NUMERIC NOT NULL,
    created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP
);


COMMIT;

-- Verification
SELECT 'Import completed!' as status;
SELECT COUNT(*) as total_players FROM players;
SELECT COUNT(*) as total_metrics FROM player_metrics;
